    frame = grid[0][0]
    left = next(c for c in range(1, w) if all(grid[r][c] == 0 for r in range(h)))
    bands = [r for r in range(h) if all(grid[r][c] == frame for c in range(left))]
    masks = [{(r-a-1, c-1) for r in range(a+1, b)
              for c in range(1, left-1) if grid[r][c] == 0}
             for a, b in zip(bands, bands[1:])]

    # Group all cells of each color, including disconnected portions of a figure.
    by_color = {}
    for r in range(h):
        for c in range(left+1, w):
            color = grid[r][c]
            if color:
                by_color.setdefault(color, []).append((r, c))
    objects = []
    for color, cells in by_color.items():
        min_y = min(y for y, x in cells)
        min_x = min(x for y, x in cells)
        objects.append((color, {(y-min_y, x-min_x) for y, x in cells}))

    # In these demonstrations the silhouettes correspond to colored objects by
    # the objects' top-to-bottom position, not by congruent shape.
    ordered_colors = sorted(objects, key=lambda item: min(y for y, x in by_color[item[0]]))
    output = [row[:left] for row in grid]
    for i, mask in enumerate(masks):
        color = ordered_colors[i][0]
        for dy, dx in mask:
            output[bands[i]+1+dy][dx+1] = color
    return output

